from pathlib import Path
import re,json
D=Path(__file__).resolve().parent;html=(D/'index.html').read_text();markup=html.split('<main>',1)[1].split('</main>',1)[0].replace('<h1>','<h3>').replace('</h1>','</h3>');markup=re.sub(r'id="([^"]+)"',r'data-rotation-role="\1"',markup)
viewer=(D/'viewer.js').read_text().replace('document.getElementById','get').replace('window.RotationReview','root.rotationReview').replace('id:key,type:',"id:uid+'-'+key,type:").replace('label.append(input);',"input.dataset.rotationRole=key;label.append(input);")
mesh=(D/'mesh-viewer.js').read_text().replace('document.getElementById','get').replace('window.RotationMeshReview','root.rotationMeshReview').replace('RotationReview.state','root.rotationReview.state').replace("document.querySelectorAll('#controls input')",'''root.querySelectorAll('[data-rotation-role="controls"] input')''').replace('function draw(){if(gl.isContextLost())return;', 'function draw(){if(disposed||gl.isContextLost())return;').replace('function update(){try{','function update(){if(disposed)return;try{').replace('buffer=gl.createBuffer();','for(const shader of gl.getAttachedShaders(program))gl.deleteShader(shader);buffer=gl.createBuffer();').replace('new ResizeObserver(draw).observe(canvas);','const resizeObserver=new ResizeObserver(draw);resizeObserver.observe(canvas);disposers.push(()=>resizeObserver.disconnect());disposers.push(()=>{if(!gl.isContextLost()){gl.useProgram(null);gl.bindBuffer(gl.ARRAY_BUFFER,null);gl.deleteBuffer(buffer);gl.deleteProgram(program);}});')
code='''(function(){let serial=0;function render(item){if(item?.props?.scenario!=='phys.5.frontier.rotation')return null;const root=document.createElement('section');root.className='card physics-rotation-lab';const uid='rotation-'+(++serial),RotationCore=window.RotationCore,RotationDensity=window.RotationDensity;let disposed=false,mounted=false;const disposers=[];root.innerHTML='''+json.dumps(markup)+''';const get=key=>root.querySelector('[data-rotation-role="'+key+'"]');\n'''+viewer+'\n'+mesh+'''\nroot.dispose=()=>{if(disposed)return;disposed=true;for(const dispose of disposers)dispose();root.dataset.disposed='true';};const lifecycle=new MutationObserver(()=>{if(root.isConnected)mounted=true;else if(mounted)root.dispose();});lifecycle.observe(document,{childList:true,subtree:true});disposers.push(()=>lifecycle.disconnect());return root;}window.PrimerRotationLab={render};})();\n'''
(D/'adapter.js').write_text(code)
css=html.split('<style>',1)[1].split('</style>',1)[0];css=css.replace('body{','.physics-rotation-lab{').replace('main{','.physics-rotation-lab{')
css=re.sub(r'(?<=})([^{}]+)\{',lambda m:','.join('.physics-rotation-lab '+s.strip()if not s.strip().startswith('.physics-rotation-lab')else s.strip()for s in m[1].split(','))+'{',css)
css=css.replace('#controls','[data-rotation-role="controls"]')
(D/'adapter.css').write_text(css)
(D/'adapter-test.html').write_text('<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="adapter.css"><body><script src="core-browser.js"></script><script src="density-browser.js"></script><script src="adapter.js"></script><script>for(let i=0;i<2;i++)document.body.append(PrimerRotationLab.render({props:{scenario:"phys.5.frontier.rotation"}}));</script></body></html>')
